target.css:
:root {
  --ink: #2d241f;
  --muted: #76685d;
  --paper: #fffaf0;
  --cream: #f5ead8;
  --line: #dfcdb4;
  --cocoa: #703f2d;
  --coral: #d85d42;
  --gold: #d89e32;
  --mint: #417b68;
}

.batch-board {
  width: 500px;
  box-sizing: border-box;
  padding: 16px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: var(--paper);
  color: var(--ink);
}

.board-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--line);
}

.title-block {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.eyebrow {
  margin: 0;
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

h1,
h2 {
  margin: 0;
}

h1 {
  font-size: 22px;
  line-height: 1.05;
  letter-spacing: -0.04em;
}

.stage {
  padding: 6px 9px;
  border-radius: 999px;
  background: var(--cocoa);
  color: var(--paper);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.06em;
}

.board-grid {
  display: grid;
  grid-template-columns: 1.45fr 1fr;
  gap: 12px;
  padding: 12px 0;
}

.ferment-panel {
  padding: 13px;
  border: 1px solid var(--line);
  border-radius: 13px;
  background: var(--cream);
}

.panel-top,
.temp-row,
.board-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.panel-top {
  margin-bottom: 10px;
}

h2 {
  font-size: 14px;
  line-height: 1;
}

.tank-id {
  color: var(--cocoa);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.08em;
}

.temp-row {
  align-items: flex-end;
  margin-bottom: 10px;
}

.temp-value {
  color: var(--coral);
  font-size: 32px;
  line-height: 0.85;
  letter-spacing: -0.06em;
}

.temp-copy {
  margin: 0;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.25;
  text-align: right;
}

.thermal-bar {
  height: 8px;
  overflow: hidden;
  border-radius: 999px;
  background: var(--line);
}

.thermal-fill {
  display: block;
  width: 76%;
  height: 100%;
  border-radius: inherit;
  background: var(--coral);
}

.readings {
  display: flex;
  justify-content: space-between;
  margin: 12px 0 0;
  padding: 0;
  list-style: none;
}

.reading {
  display: flex;
  flex-direction: column;
  gap: 2px;
  color: var(--muted);
  font-size: 10px;
}

.reading b {
  color: var(--ink);
  font-size: 12px;
}

.metric-stack {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.metric {
  display: flex;
  flex-direction: column;
  justify-content: center;
  min-height: 58px;
  padding: 9px 10px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--paper);
}

.metric-label,
.metric-delta {
  color: var(--muted);
  font-size: 10px;
  line-height: 1.1;
}

.metric-value {
  margin: 3px 0;
  font-size: 21px;
  line-height: 0.9;
  letter-spacing: -0.04em;
}

.metric-acid .metric-value {
  color: var(--mint);
}

.metric-brix .metric-value {
  color: var(--gold);
}

.note {
  grid-column: 1 / -1;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 10px;
  border-radius: 10px;
  background: var(--cocoa);
  color: var(--paper);
}

.note-mark {
  display: grid;
  width: 18px;
  height: 18px;
  place-items: center;
  border-radius: 50%;
  background: var(--gold);
  color: var(--ink);
  font-size: 12px;
  font-weight: 900;
}

.note p {
  margin: 0;
  font-size: 11px;
  line-height: 1.2;
}

.board-foot {
  padding-top: 11px;
  border-top: 1px solid var(--line);
}

.foot-note {
  margin: 0;
  color: var(--muted);
  font-size: 10px;
}

button {
  padding: 8px 12px;
  border: 0;
  border-radius: 8px;
  background: var(--coral);
  color: var(--paper);
  font-size: 12px;
  font-weight: 800;
}
